export function InfiniteList() {
  const [items, setItems] = useState<any[]>([]);
  const [page, setPage] = useState(1);
  const sentinel = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const obs = new IntersectionObserver(async (entries) => {
      if (entries[0].isIntersecting) {
        const more = await fetchMoreData(page);
        setItems((p) => [...p, ...more]);
        setPage((p) => p + 1);
      }
    });
    if (sentinel.current) obs.observe(sentinel.current);
    return () => obs.disconnect();
  }, [page]);

  return (
    <div>
      {items.map((it, i) => <div key={i} className="border-b p-3">{it.title}</div>)}
      <div ref={sentinel} className="h-10" />
    </div>
  );
}

const express = require('express');
const router = express.Router();
const store = new Map();

router.get('/users', (req, res) => res.json([...store.values()]));
router.get('/users/:id', (req, res) => {
  const item = store.get(req.params.id);
  if (!item) return res.status(404).json({ error: 'not found' });
  res.json(item);
});
router.post('/users', (req, res) => {
  const id = String(Date.now());
  const item = { id: id, ...req.body };
  store.set(id, item);
  res.status(201).json(item);
});
router.put('/users/:id', (req, res) => {
  if (!store.has(req.params.id)) return res.status(404).end();
  const updated = { ...store.get(req.params.id), ...req.body };
  store.set(req.params.id, updated);
  res.json(updated);
});
router.delete('/users/:id', (req, res) => {
  store.delete(req.params.id);
  res.status(204).end();
});

module.exports = router;

