    try:
        payload = jwt.decode(token, SECRET, algorithms=['HS256'])
        return payload['sub']
    except JWTError:
        raise HTTPException(401, 'bad token')

@app.get('/me')
def me(user: str = Depends(current_user)):
    return {'user': user}

